'use strict';
const demo={versions:[{id:'login-v1',name:'로그인 기본 점검',package:'login-smoke',version:'1.0.0'},{id:'account-v2',name:'계정 설정 변경',package:'account-settings',version:'2.1.0'},{id:'checkout-v1',name:'주문 핵심 경로',package:'checkout-critical',version:'1.0.2'}],selected:'login-v1',draft:{title:'로그인 기본 점검',version:'1.1.0',author:'kim',reviewer:null,state:'draft'},person:'lee',pins:[],requests:[],schedules:[],work:'in_progress',notification:'미요청'};
demo.suiteVersions=[{id:'suite-v1',name:'릴리즈 기본 점검',version:'1.0.0',cases:['login-v1','account-v2'],stop:true}];demo.selectedSuite='suite-v1';demo.suitePins=[];demo.draft.kind='qa';demo.draft.cases=['login-v1','account-v2'];demo.draft.stop=true;
const qa=()=>demo.versions.find(v=>v.id===demo.selected)||demo.versions[0];
const personName=id=>({kim:'김민수',lee:'이지현'}[id]||id);
function genericState(s){if(sample==='normal'||['W06','A05'].includes(s.id))return '';const m={empty:['항목이 없습니다','다른 프로젝트 또는 새로 고침을 선택하세요.'],loading:['불러오는 중','선택한 프로젝트의 응답을 기다립니다.'],offline:['서버 연결 끊김','연결을 확인하세요. Desktop 로컬 문서는 계속 열 수 있습니다.'],permission:['권한이 없습니다','프로젝트 membership과 해당 작업 권한을 확인하세요.'],error:['요청 처리 오류','문서를 보존했습니다. 연결을 확인하고 다시 시도하세요.'],conflict:['변경 충돌','다른 사용자가 먼저 변경했습니다. 최신 revision을 확인하세요.'],hash_error:['원문 무결성 오류','XML hash가 다릅니다. 다운로드·수신을 차단하고 버전을 다시 조회하세요.']}[sample];return m?`<section class="state-message"><h2>${m[0]}</h2><p>${m[1]}</p><button data-op="retry">정상 상태 다시 보기</button></section>`:'';}
function webNav(id){return `<aside class="web-nav"><h2>공용 웹 품질 점검</h2>${[['W01','프로젝트'],['W02','공용 QA'],['W05','실행 기록'],['A04','예약']].map(([x,t])=>`<a href="#prototype/${x}" class="${id===x?'active':''}">${t}</a>`).join('')}<hr><small>관리 업무</small>${[['A01','검수·게시'],['A03','업무·비교'],['A05','실행 운영'],['A06','감사·알림'],['A07','사용자·권한 계획'],['A08','리소스 계획']].map(([x,t])=>`<a href="#prototype/${x}" class="${id===x?'active':''}">${t}</a>`).join('')}<hr><p class="muted">${roles[role]}<br>프로젝트 범위</p></aside>`;}
function webScreen(s){return `<div class="web-shell">${webNav(s.id)}<main class="web-content"><div class="heading"><div><h1>${s.title}</h1><p>공용 웹 품질 점검</p></div>${link(s.id,'화면설계')}</div>${genericState(s)||webBody(s)}</main></div>`;}
function webBody(s){const v=qa(),sv=suite();switch(s.id){
case 'W01':return `<p>조직 계정으로 확인한 프로젝트를 선택하세요.</p><div class="row">${action('조직 로그인 예시','login')}${action('로그아웃 예시','logout')}</div><h3>내 프로젝트</h3>${table(['프로젝트','역할','최근 작업',''],[['공용 웹 품질 점검',roles[role],`게시 QA ${demo.versions.length}개`,go('프로젝트 열기','W02')],['릴리즈 회귀 점검',roles[role],'Suite 1개',go('프로젝트 열기','W02')]])}<p class="footer-note">실제 계정·세션을 만들지 않는 연결 예시입니다.</p>`;
case 'W02':{const rows=demo.versions.filter(r=>`${r.name} ${r.package} ${r.version}`.toLowerCase().includes(webFilter.toLowerCase()));return `<div class="row"><input id="qa-filter" aria-label="공용 QA 검색" placeholder="불러온 목록에서 검색" value="${esc(webFilter)}">${go('Suite 보기','W04')}<span class="push">${action('초안 작성','draft','qa_editor')}</span></div><h3>게시된 Suite</h3>${table(['Suite','고정 버전',''],demo.suiteVersions.map(v=>[esc(v.name),esc(v.version),'<button data-suite="'+v.id+'">Suite 상세</button>']))}<h3>게시된 QA</h3>${rows.length?table(['QA 이름','고정 버전','게시일',''],rows.map(r=>[`${esc(r.name)}<br><small>${esc(r.package)}</small>`,esc(r.version),'2026-11-11',`<button data-version="${r.id}">상세 보기</button>`])):'<p class="state-message">검색 결과가 없습니다.</p>'}<p class="footer-note">프로젝트 공용 QA입니다. 개인에게 배정된 업무 목록은 아닙니다.</p>`;}
case 'W03':return `<h2>${esc(v.name)} <span class="tag">${esc(v.version)}</span></h2><p>사용자가 로그인한 뒤 인사 문구를 확인합니다.</p><dl class="facts"><dt>게시 패키지</dt><dd>${esc(v.package)}</dd><dt>원본</dt><dd>고정 게시 버전 · Engine alpha.6 예시</dd><dt>내 고정 상태</dt><dd>${demo.pins.includes(v.id)?'이 버전을 고정함':'고정 전'}</dd></dl><div class="row">${action('XML 파일 다운로드','download')}${action('이 버전 고정','pin','qa_tester')}${go('Desktop 수신 흐름','D03')}</div><div class="detail-strip">Desktop에서 서버에 연결하고 같은 버전을 선택하여 새 로컬 QA로 받습니다. 파일을 내려받아 직접 열 수도 있습니다. 실행 중인 앱으로 자동 전송하는 deep link는 없습니다.</div><details><summary>원문·무결성 상세</summary><p>원문 SHA는 bytes 무결성, snapshot hash는 정규화된 실행 정의의 동일성입니다.</p><pre>${esc(window.DEMO_XML)}</pre></details>${go('Suite case 보기','W04')}`;
case 'W04':{const sv=suite();return `<h2>${esc(sv.name)} <span class="tag">Suite ${esc(sv.version)}</span></h2><p>${demo.suitePins.includes(sv.id)?'이 Suite 버전을 고정했습니다.':'Suite 버전 고정 전'}</p><p>${sv.stop?'실패하면 후속 case를 중지합니다.':'실패 후에도 다음 case를 진행합니다.'} 각 case의 고정 버전을 유지합니다.</p>${table(['순서','Case','게시 버전',''],sv.cases.map((id,i)=>{const cv=demo.versions.find(v=>v.id===id);return [String(i+1),esc(cv.name),esc(cv.version),'<button data-version="'+id+'">Case 상세</button>'];}))}<div class="row" style="margin-top:20px">${action('Suite 버전 고정','suite-pin','qa_tester')}${go('Agent 전체 Suite 요청','W08')}${go('Case 하나를 Desktop에서 받기','D03')}</div><p class="footer-note">Desktop 전체 Suite 일괄 실행은 미구현입니다. 서버 Registry Suite와 Engine raw Suite 문서는 구분합니다.</p>`;}
case 'W05':return `${table(['QA / 실행시각','실행 판정','증거','업무',''],[['로그인 기본 점검<br><small>11월 11일 12:40</small>','실패','확인됨','진행 중',go('결과 보기','W06')],['계정 설정 변경<br><small>11월 11일 12:31</small>','통과','확인됨','대기','<button data-result="passed">결과 보기</button>']])}<h3>아직 결과가 없는 요청</h3>${demo.requests.length?table(['요청','상태',''],demo.requests.map(r=>[esc(r.title),r.status,go('요청 보기','A05')])):'<p>대기 중인 요청이 없습니다.</p>'}<div class="row">${go('새 Agent 실행 요청','W08')}${go('요청·진행 확인','A05')}</div>`;
case 'W06':return resultView();
case 'W07':return `<p>공개 XML/JSON을 검사·전달합니다. Desktop 파일 블록 작업실과 별도 도구입니다.</p><label class="form-stack">XML 원문<textarea id="web-xml" spellcheck="false">${esc(window.DEMO_XML)}</textarea></label><div class="row" style="margin-top:16px">${action('파일 선택','choose-xml')}${action('목업 구문 확인','xml-check')}${go('Desktop 직접 XML','D06')}</div><input hidden id="xml-file" type="file" accept=".xml,.json"><p class="footer-note">구문 확인은 Engine validation이 아닙니다. 웹은 실제 테스트를 실행하지 않습니다.</p>`;
case 'W08':return `<h2>고정 버전으로 실행 요청</h2><div class="form-stack"><label>대상<select id="request-target"><option value="suite:${sv.id}">${esc(sv.name)} · Suite ${esc(sv.version)}</option><option value="qa:${v.id}">${esc(v.name)} · ${esc(v.version)}</option></select></label><label>허용 리소스<select><option>qa-web-chromium · web</option></select></label><label>환경<input value="staging" readonly></label></div><p>Agent가 허용 정책과 리소스를 확인한 후 실행합니다.</p>${action('Agent에 실행 요청 예시','request','qa_tester')}<p class="footer-note">접수는 실행 완료가 아닙니다. 기본 Agent runtime은 alpha.6입니다.</p>`;
case 'A01':return `${table(['초안','작성자','검수 상태',''],[[`${esc(demo.draft.title)} ${esc(demo.draft.version)}`,personName(demo.draft.author),draftLabel(),go('검수 상세','A02')]])}<div class="row" style="margin-top:18px">${action('새 초안 작성','draft','qa_editor')}</div><p class="footer-note">수정·반려·폐기 API는 현재 미구현입니다. 기존 버전 대신 새 초안을 만듭니다.</p>`;
case 'A02':return reviewView();
case 'A03':return `<h2>로그인 기본 점검 · 실행 실패</h2><div class="state-axes"><div><small>원본 실행 판정</small><b>실패 · 변경 불가</b></div><div><small>업무 상태</small><b>${workLabel()}</b></div><div><small>비교</small><b>동일 환경 기준 필요</b></div></div><div class="form-stack"><label>담당자<select><option>이지현</option><option>김민수</option></select></label><label>업무 상태<select id="workflow">${[['todo','대기'],['in_progress','진행 중'],['done','완료']].map(([x,t])=>`<option value="${x}" ${x===demo.work?'selected':''}>${t}</option>`).join('')}</select></label></div><div class="row" style="margin-top:16px">${action('업무 변경 저장 예시','work','qa_tester')}${action('이전 실행 비교 예시','compare','viewer')}${go('원본 결과','W06')}</div><p class="footer-note">done은 passed가 아닙니다. 비교는 snapshot/target/runtime/profile/reference/environment 조건을 확인합니다.</p>`;
case 'A04':return `<h2>주간 릴리즈 기본 점검</h2><div class="form-stack"><label>고정 Suite<select id="schedule-suite">${demo.suiteVersions.map(x=>`<option value="${x.id}" ${x.id===sv.id?'selected':''}>${esc(x.name)} ${esc(x.version)}</option>`).join('')}</select></label><div class="row"><label>요일<select id="schedule-day"><option>월요일</option><option>수요일</option></select></label><label>시각<input id="schedule-time" type="time" value="09:00"></label><label>시간대<select id="schedule-zone"><option>Asia/Seoul</option><option>UTC</option></select></label></div><label>리소스<select><option>qa-web-chromium</option></select></label></div><div class="row" style="margin-top:20px">${action('예약 저장 예시','schedule','qa_tester')}${action('최근 예약 중지 예시','pause-schedule','qa_tester')}</div><h3>예약과 발생 이력</h3>${table(['예정 시각','상태','다음 행동'],[...demo.schedules.map((r,i)=>[esc(r.title+' '+r.version)+'<br>'+esc(r.when),r.active?'활성':'중지',action('발생 시각 도달 예시',`occurrence:${i}`,'qa_tester')]),['11월 9일 09:00','미실행 · Agent 없음',go('운영 확인','A05')]])}<p class="footer-note">실행자도 예약할 수 있습니다. 관리 메뉴 위치가 관리자 전용 권한을 뜻하지 않습니다.</p>`;
case 'A05':return operationsView();
case 'A06':return `<h2>감사 기록</h2>${allowed('qa_manager')?table(['시각','행위자','행동','결과'],[['12:30','이지현','독립 검수','승인'],['12:32','김민수','새 버전 게시','완료'],['12:45','이지현','실행 업무','revision 갱신']]):'<p class="state-message">감사 기록 조회는 QA 관리자 이상 권한이 필요합니다.</p>'}<h3>실행 알림</h3><p>전달 상태: ${demo.notification}</p>${action('알림 전송 요청 예시','notification','qa_manager')}<p class="footer-note">현재 local-test HTTP fixture입니다. 외부 Slack 발송은 미완료이며 별도 수동 재시도 API는 없습니다.</p>`;
case 'A07':return plannedView('사용자·팀·권한',[['프로젝트','공용 웹 품질 점검'],['사용자','이지현'],['팀','QA 팀'],['역할','QA 실행자']],['초대·비활성·역할 변경 API와 감사 계약','membership 격리와 승격 권한','개인 QA 할당은 별도 요구 정의']);
case 'A08':return plannedView('Agent·리소스 관리',[['Agent','qa-agent-01'],['리소스','web-chromium'],['가용 상태','확인 전'],['플랫폼','web']],['재고 조회·등록 HTTP 계약','capability·lease·격리 상태 소유','실제 기기 연결 증거와 등록 정보 분리']);
default:return '';}}
const suite=()=>demo.suiteVersions.find(v=>v.id===demo.selectedSuite)||demo.suiteVersions[0];
function draftLabel(){return {draft:'검수 대기',reviewed:'검수 승인',published:'게시됨'}[demo.draft.state];}
function workLabel(){return {todo:'대기',in_progress:'진행 중',done:'완료'}[demo.work];}
function reviewView(){const d=demo.draft;return `<div class="row"><h2>${esc(d.title)} ${esc(d.version)}</h2><span class="tag">${draftLabel()}</span></div><dl class="facts"><dt>초안 종류</dt><dd><select id="draft-kind"><option value="qa" ${d.kind!=='suite'?'selected':''}>QA XML</option><option value="suite" ${d.kind==='suite'?'selected':''}>Suite</option></select></dd><dt>작성자</dt><dd>${personName(d.author)}</dd><dt>검수자</dt><dd>${d.reviewer?personName(d.reviewer):'검수 전'}</dd><dt>현재 사용자</dt><dd><select id="review-person"><option value="lee" ${demo.person==='lee'?'selected':''}>이지현 · ${d.author==='lee'?'작성자 본인':'다른 검수자'}</option><option value="kim" ${demo.person==='kim'?'selected':''}>김민수 · ${d.author==='kim'?'작성자 본인':'다른 검수자'}</option></select></dd></dl><div class="columns"><section><h3>기존 게시 버전 1.0.0</h3><pre>페이지 열기<br>사용자 정보 입력<br>로그인 버튼 클릭</pre></section><section><h3>새 초안</h3><div class="form-stack"><label>QA 제목<input id="draft-title" value="${esc(d.title)}" ${d.state==='draft'?'':'readonly'}></label><label>새 버전<input id="draft-version" value="${esc(d.version)}" ${d.state==='draft'?'':'readonly'}></label></div>${d.kind==='suite'?`<h3>고정 case 순서</h3><select id="suite-order"><option value="normal" ${d.cases?.[0]==='login-v1'?'selected':''}>로그인 1.0.0 → 계정 설정 2.1.0</option><option value="reverse" ${d.cases?.[0]==='account-v2'?'selected':''}>계정 설정 2.1.0 → 로그인 1.0.0</option></select><p><label><input type="checkbox" id="suite-stop" ${d.stop?'checked':''}> 실패하면 후속 case 중지</label></p>`:'<pre>로그인 뒤 인사 문구 확인 단계 추가</pre>'}</section></div><div class="row">${action('새 초안 저장 예시','save-draft','qa_editor')}${action('독립 검수 승인 예시','review','qa_manager',demo.person===d.author||d.state!=='draft'?'disabled title="작성자 본인은 검수할 수 없으며 검수 대기 초안만 가능합니다"':'')}${action('새 버전 게시 예시','publish','qa_manager',d.state!=='reviewed'?'disabled title="독립 검수 승인이 먼저 필요합니다"':'')}${go('공용 QA 목록','W02')}</div><p class="detail-strip">작성자는 자신의 초안을 검수할 수 없습니다. 게시 시 활성 검수 권한을 다시 확인합니다. 현재 조작은 예시 상태만 변경합니다.</p>`;}
function resultView(){if(sample==='incompatible')return `<h2>로컬 실행과 공유 상태</h2><div class="state-axes"><div><small>Desktop alpha.8 로컬 결과</small><b>passed · 통과 유지</b></div><div><small>기본 서버 alpha.6 공유</small><b>runtime 호환성 불일치 · 거부</b></div></div><p>이 로컬 실행은 서버 실행 기록으로 새로 등록되지 않았습니다. 기존 서버 Agent 실행 결과와 혼합하지 않습니다.</p>${go('Desktop 공유 제한 보기','D07')}`;const outcome=sample==='passed'?'통과':sample==='missing_evidence'?'환경 오류':'실패';return `<div class="row"><div><div class="outcome ${sample==='passed'?'passed':'failed'}">${outcome}</div><h2>로그인 기본 점검</h2></div><span class="push tag">서버 Agent · alpha.6 예시</span></div><div class="state-axes"><div><small>실행 판정</small><b>${outcome}</b></div><div><small>요청·lease</small><b>완료</b></div><div><small>증거 정합</small><b>${sample==='missing_evidence'?'수집된 화면 없음':'확인됨 · 예시'}</b></div><div><small>업무</small><b>${workLabel()}</b></div><div><small>예약 발생</small><b>수동 요청 · 해당 없음</b></div><div><small>Desktop 공유</small><b>${sample==='incompatible'?'runtime 호환성 불일치':'서버 실행과 별도'}</b></div></div><div class="split"><section><h3>단계 관측</h3><div class="timeline"><p>브라우저 열기 · ${sample==='missing_evidence'?'환경 오류':'통과'}</p><p>사용자 정보 입력 · ${sample==='missing_evidence'?'미실행':'통과'}</p><p>인사 문구 확인 · ${sample==='missing_evidence'?'미실행':outcome}</p></div>${sample==='failed'||sample==='normal'?'<p>예상: Welcome qa-user<br>관측: 로그인 정보를 확인해 주세요.</p>':''}</section><aside class="panel"><h3>화면 증거</h3><p>${sample==='missing_evidence'?'브라우저 시작 실패로 수집된 화면 증거가 없습니다.':'현재 그림은 단계 설명용입니다. 실제 PNG는 기존 검증 근거에서 확인합니다.'}</p>${link('W06','실제 증거 근거')}</aside></div><div class="row">${go('업무·비교','A03')}${go('실행 운영','A05')}</div><details><summary>진단·식별 정보</summary><p>snapshot, event sequence, runtime version, artifact hash를 해당 run에 귀속합니다. 원본 판정은 변경하지 않습니다.</p></details>`;}
function operationsView(){const r=demo.requests.at(-1),status=sample==='normal'?(r?.status||'queued'):({running:'claimed',cancel_requested:'cancel_requested',cancelled:'cancelled',infra_error:'quarantined'}[sample]||'queued'),labels={queued:'대기 중',claimed:'실행 중',cancel_requested:'취소 요청 중',cancelled:'취소됨',quarantined:'격리됨 · 종료 확인 필요',recovered:'격리 해제 · 이전 결과 미확정'};return `<h2>${esc(r?.title||'릴리즈 기본 점검')} · ${labels[status]}</h2><div class="state-axes"><div><small>요청 상태</small><b>${labels[status]}</b></div><div><small>실행 판정</small><b>${status==='cancelled'?'cancelled':'결과 미확정'}</b></div><div><small>증거</small><b>수집된 증거 없음</b></div></div><div class="timeline"><p>${r?'예시 요청 접수됨':'기존 요청 설명 예시'}</p><p>Agent qa-agent-01 · 리소스 web-chromium</p><p>Engine alpha.6 · ordered cases</p></div><div class="row">${action('취소 요청 예시','cancel','qa_tester')}${status==='cancel_requested'?action('종료 응답 예시 보기','cancelled'):''}${go('서버 실행 기록','W05')}</div><details ${status==='quarantined'?'open':''}><summary>불확실 실행 운영 복구</summary><p>lease 만료는 프로세스 종료 증거가 아닙니다. 이전 작업과 대상 상태를 확인하세요.</p><label><input type="checkbox" id="recovery-check"> 이전 실행 종료와 대상 안전 상태 확인</label><label class="form-stack">처리 사유<input id="recovery-reason" placeholder="확인한 내용"></label>${action('격리 해제 요청 예시','recovery','qa_manager',status!=='quarantined'?'disabled title="격리된 실행에서만 가능합니다"':'')}</details><p class="footer-note">복구는 이전 실행의 성공이나 자동 재실행을 의미하지 않습니다.</p>`;}
function plannedView(title,fields,criteria){return `<section class="planned"><span class="tag proposal">후속 설계 · API/제품 UI 미구현</span><h2 style="margin-top:14px">${title}</h2><div class="form-stack">${fields.map(([a,b])=>`<label>${a}<input value="${b}" readonly></label>`).join('')}</div><div class="row" style="margin-top:18px"><button disabled title="서버 계약과 구현이 선행되어야 합니다">등록</button><button disabled title="변경 권한·감사 계약 미구현">변경 저장</button></div><h3>구현 전 인수 조건</h3>${list(criteria)}<p>현재 환경 provisioning과 이 관리 CRUD 화면은 서로 다른 범위입니다.</p></section>${go('현재 실행 운영','A05')}`;}
function engineView(){return `<main class="page" style="overflow:auto;width:100%"><div class="heading"><div><h1>독립 Engine 공개 계약</h1><p>제품 GUI가 아닌 package/CLI 입출력 검토입니다.</p></div>${link('E01')}</div><div class="columns"><section><h2>입력과 준비</h2><pre>외부 Node 프로젝트 / CI / Desktop / Agent<br>  ↓ 공개 XML/JSON/YAML + 실행 설정<br>import / validate<br>  ↓ 오류가 없을 때<br>plan → canonical snapshot<br>  ↓ 별도 명시 실행<br>run → events / result / evidence</pre><p>validate/plan은 브라우저를 시작하지 않습니다. 한 Blueprint는 한 target/session입니다.</p><div class="row">${action('검증 오류 예시','engine-invalid')}${action('실행 중 예시','engine-run')}</div><h3>지원 경계</h3><p>Chromium 실제 인수. Appium protocol fixture는 실기기 인수와 구분합니다. TV/임의 shell/native include는 지원하지 않습니다.</p></section><section class="panel"><h2>${stateNames[sample]}</h2>${sample==='validation_error'?'<p>INVALID_FLOW · 연결되지 않은 노드. 실행 미시작이며 결과가 없습니다.</p>':sample==='normal'?'<p>검증과 plan 이후 명시 실행을 기다립니다.</p>':`<p>${stateNames[sample]} 예시입니다. 실제 호출하지 않습니다.</p><pre>run.started<br>step.started<br>step.finished<br>step.retrying<br>run.finished</pre><p>이것은 가능한 event 종류 목록입니다. skipped는 step outcome이며 별도 step.skipped event가 아닙니다.</p>`}<details><summary>결과 계약</summary><p>passed / failed / blocked / infra_error / cancelled</p><p>unrun은 미실행 표시입니다. 업무 상태는 Checker가 소유합니다.</p><p>원문 byte hash와 canonical snapshot hash는 다릅니다.</p></details><div class="row">${link('D07')}${link('A05')}</div></section></div></main>`;}
function handleOperation(op){
 if(op==='retry'){sample='normal';render();}else if(op==='draft'){demo.draft={title:'로그인 기본 점검',version:'1.1.0',author:'kim',reviewer:null,state:'draft',kind:'qa',cases:['login-v1','account-v2'],stop:true};location.hash='prototype/A02';render();}
 else if(op==='save-draft'){demo.draft={kind:$('#draft-kind').value,cases:$('#suite-order')?.value==='reverse'?['account-v2','login-v1']:['login-v1','account-v2'],stop:$('#suite-stop')?.checked??true,title:$('#draft-title').value.trim()||'새 QA',version:$('#draft-version').value.trim()||'1.1.0',author:demo.person,reviewer:null,state:'draft'};render();notify('새 초안 예시 저장. 다른 사용자의 검수가 필요합니다.');}
 else if(op==='review'){if(!allowed('qa_manager')||demo.person===demo.draft.author)return;demo.draft.reviewer=demo.person;demo.draft.state='reviewed';render();}
 else if(op==='publish'){if(!allowed('qa_manager')||demo.draft.state!=='reviewed'||demo.draft.reviewer===demo.draft.author)return;const d=demo.draft,collection=d.kind==='suite'?demo.suiteVersions:demo.versions;if(collection.some(v=>(d.kind==='suite'||v.package==='login-smoke')&&v.version===d.version)){notify('같은 package/version은 이미 게시되어 있습니다. 새 버전 초안을 만드세요.');return;}const id='published-'+d.kind+'-'+collection.length;collection.push({id,name:d.title,package:d.kind==='suite'?'release-readiness':'login-smoke',version:d.version,cases:d.cases,stop:d.stop});d.state='published';if(d.kind==='suite'){demo.selectedSuite=id;location.hash='prototype/W04';}else{demo.selected=id;location.hash='prototype/W03';}}
 else if(op==='pin'){if(!demo.pins.includes(demo.selected))demo.pins.push(demo.selected);render();notify('예시 버전 고정. 실행하지 않았습니다.');}else if(op==='suite-pin'){const sv=suite();if(!demo.suitePins.includes(sv.id))demo.suitePins.push(sv.id);render();notify('Suite '+sv.version+' 고정 예시. 실행하지 않았습니다.');}
 else if(op==='request'){const [kind,id]=$('#request-target').value.split(':');const source=(kind==='suite'?demo.suiteVersions:demo.versions).find(v=>v.id===id);demo.requests.push({title:source.name+' '+source.version,kind,versionId:id,version:source.version,cases:source.cases,status:'queued'});location.hash='prototype/A05';}
 else if(op==='schedule'){const sv=demo.suiteVersions.find(v=>v.id===$('#schedule-suite').value);demo.schedules.push({suiteId:sv.id,version:sv.version,title:sv.name,cases:[...sv.cases],when:`${$('#schedule-day').value} ${$('#schedule-time').value} ${$('#schedule-zone').value}`,active:true});render();}
 else if(op==='pause-schedule'){if(demo.schedules.length)demo.schedules.at(-1).active=false;render();}
 else if(op.startsWith('occurrence:')){const chosen=demo.schedules[Number(op.split(':')[1])];if(chosen?.active){demo.requests.push({title:`예약 발생 · ${chosen.when} · ${chosen.title} ${chosen.version}`,versionId:chosen.suiteId,version:chosen.version,cases:[...chosen.cases],status:'queued'});location.hash='prototype/A05';}else notify('중지된 예약은 새 occurrence를 만들지 않습니다.');}
 else if(op==='work'){demo.work=$('#workflow').value;render();}else if(op==='compare')notify('환경 정보가 부족하여 비교 불가. 원본 결과는 유지됩니다.');
 else if(op==='cancel'||op==='cancelled'){sample=op==='cancel'?'cancel_requested':'cancelled';if(demo.requests.length)demo.requests.at(-1).status=sample;render();}
 else if(op==='recovery'){if($('#recovery-check').checked&&$('#recovery-reason').value.trim()){if(demo.requests.length)demo.requests.at(-1).status='recovered';sample='normal';render();notify('격리 해제 예시. 이전 결과와 재실행은 바뀌지 않습니다.');}else notify('종료·대상 상태 확인과 처리 사유가 필요합니다.');}
 else if(op==='notification'){demo.notification='전송 실패 · local-test 예시';render();}else if(op==='login')notify('조직 연결 예시 · 실제 로그인 없음');else if(op==='logout'){sample='offline';render();}
 else if(op==='engine-invalid'){sample='validation_error';render();}else if(op==='engine-run'){sample='running';render();}
 else if(op==='download'){const url=URL.createObjectURL(new Blob([window.DEMO_XML],{type:'application/xml'}));const a=document.createElement('a');a.href=url;a.download='login-example.xml';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);notify('공개 XML fixture 다운로드. 목업은 실행하지 않습니다.');}
 else if(op==='choose-xml')$('#xml-file').click();else if(op==='xml-check'){const p=new DOMParser().parseFromString($('#web-xml').value,'application/xml');notify(p.querySelector('parsererror')?'XML 구문 오류 · 실행 없음':'XML 구문만 확인 · Engine 검증 아님');}
}
document.addEventListener('click',e=>{const suiteLink=e.target.closest('[data-suite]');if(suiteLink){demo.selectedSuite=suiteLink.dataset.suite;location.hash='prototype/W04';}const v=e.target.closest('[data-version]');if(v){demo.selected=v.dataset.version;location.hash='prototype/W03';}const r=e.target.closest('[data-result]');if(r){location.hash='prototype/W06';setTimeout(()=>{sample=r.dataset.result;render();},0);}});
document.addEventListener('change',async e=>{if(e.target.id==='draft-kind'){demo.draft.kind=e.target.value;demo.draft.title=e.target.value==='suite'?'릴리즈 기본 점검':'로그인 기본 점검';demo.draft.state='draft';demo.draft.reviewer=null;render();}if(e.target.id==='review-person'){demo.person=e.target.value;render();}if(e.target.id==='xml-file'&&e.target.files[0]){const f=e.target.files[0];if(f.size>1024*1024){notify('1MiB 이하 파일만 검토합니다.');return;}$('#web-xml').value=await f.text();}});
render();
